args<-commandArgs(trailingOnly=TRUE);stopifnot(length(args)==3L)
.libPaths(c(normalizePath('build/literature-review/signac-runtime/motif-reference-setup-1/R-lib'),normalizePath('build/literature-review/signac-runtime/reference-setup-1/R-lib'),normalizePath('build/omics-sctransform-r'),.Library),include.site=FALSE)
stopifnot(as.character(packageVersion('Signac'))=='1.17.1',as.character(packageVersion('motifmatchr'))=='1.34.0',!requireNamespace('wrswoR',quietly=TRUE));BiocParallel::register(BiocParallel::SerialParam())
source('src/main/resources/org/jlinalg/omics/signac_motif_legacy_access.R');input<-jsonlite::read_json(args[[1]],simplifyVector=FALSE);resource<-'src/main/resources/org/jlinalg/omics/signac-scan';profiles<-jsonlite::read_json(file.path(resource,'SOURCE-PROFILES.json'),simplifyVector=FALSE);envs<-list()
source('src/main/resources/org/jlinalg/omics/signac_scan_legacy_fasta.R')
for(profile in profiles$records){env<-new.env(parent=asNamespace('Signac'));for(f in profile$functions)sys.source(file.path(resource,f$resource),env,keep.source=FALSE);if(profile$profile=='1.17.1-package')for(name in ls(env))stopifnot(identical(body(env[[name]]),body(get(name,asNamespace('Signac')))));if(profile$profile!='1.17.1-package')env$GetAssayData<-signac_motif_legacy_get_assay_data;envs[[profile$profile]]<-env}
capture<-function(f){warnings<-character();value<-tryCatch(withCallingHandlers(f(),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart('muffleWarning')}),error=function(e)list(error=conditionMessage(e)));list(value=value,warnings=warnings)}
canonicalGetSeq<-BSgenome::getSeq
ids<-function(values,names)if(length(values)==0L)character() else vapply(values,function(v)if(is.numeric(v))names[[as.integer(v)+1L]] else v,character(1))
results<-list()
for(profile in input$profiles)for(case in input$cases){
 index<-length(results);folder<-file.path(args[[3]],sprintf('control-%03d',index));dir.create(folder);d<-input$datasets[[case$dataset]];env<-envs[[profile]];object<-NULL;meta<-NULL;features<-NULL;background<-NULL;before<-NULL;after<-NULL
 result<-capture(function(){
  fasta<-file.path(folder,'reference.fa');connection<-file(fasta,'wb');for(name in names(d$sequences)){text<-paste0('>',name,'\n',d$sequences[[name]],'\n');if(isTRUE(d$crlf))text<-gsub('\n','\r\n',text,fixed=TRUE);writeBin(charToRaw(text),connection)};close(connection);Rsamtools::indexFa(fasta);genome<-Rsamtools::FaFile(fasta);if(profile=='1.6.0-source'){bridge<-signac_scan_legacy_fasta(genome);on.exit(bridge$restore(),add=TRUE);genome<-bridge$genome}
  peaks<-GenomicRanges::GRanges(vapply(d$peaks,`[[`,character(1),'chromosome'),IRanges::IRanges(vapply(d$peaks,`[[`,numeric(1),'start'),vapply(d$peaks,`[[`,numeric(1),'end')));peak.names<-paste0(as.character(GenomeInfoDb::seqnames(peaks)),'-',GenomicRanges::start(peaks),'-',GenomicRanges::end(peaks));names(peaks)<-peak.names
  pfm<-do.call(TFBSTools::PFMatrixList,lapply(d$pfms,function(m){matrix<-t(do.call(rbind,lapply(m$rows,unlist)));rownames(matrix)<-c('A','C','G','T');TFBSTools::PFMatrix(ID=m$id,name=m$name,strand='+',bg=setNames(unlist(m$background),c('A','C','G','T')),profileMatrix=matrix)}));names(pfm)<-vapply(d$pfms,`[[`,character(1),'id')
  motif<-if(profile=='1.17.1-package')Signac::AddMotifs(peaks,genome=genome,pfm=pfm,verbose=FALSE) else env$AddMotifs.default(peaks,genome=genome,pfm=pfm,verbose=FALSE);stats<-if(profile=='1.17.1-package')Signac::RegionStats(peaks,genome=genome,verbose=FALSE) else env$RegionStats.default(peaks,genome=genome,verbose=FALSE);stats<-as.data.frame(stats);motif.matrix<-Signac::GetMotifData(motif,slot='data');positions<-Signac::GetMotifData(motif,slot='positions');Matrix::writeMM(motif.matrix,file.path(folder,'motif-presence.mtx'));saveRDS(motif,file.path(folder,'motif.rds'));counts<-as(Matrix::Matrix(do.call(rbind,lapply(d$counts,unlist)),sparse=TRUE),'dgCMatrix');dimnames(counts)<-list(peak.names,unlist(d$cells));assay<-Signac::CreateChromatinAssay(counts=counts,ranges=peaks,motifs=motif,min.cells=0,min.features=0);rownames(stats)<-peak.names;stats$count<-Matrix::rowSums(counts);meta<<-stats;assay<-SeuratObject::AddMetaData(assay,stats);object<<-SeuratObject::CreateSeuratObject(counts=assay,assay='peaks');features<<-ids(case$query,peak.names);background<<-if(is.null(case$background))NULL else if(is.numeric(case$background))case$background else ids(case$background,peak.names)
  RNGkind('Mersenne-Twister','Inversion','Rejection');set.seed(case$seed);before<<-.Random.seed;fun<-if(profile=='1.17.1-package')Signac::FindMotifs else env$FindMotifs;enrichment<-fun(object,features=features,background=background,assay='peaks',verbose=FALSE,p.adjust.method=case$adjustment,features.match=unlist(case$features_match));after<<-.Random.seed
  list(enrichment=enrichment,metadata=stats,motif_matrix=as.matrix(motif.matrix),motif_ids=colnames(motif.matrix),motif_names=Signac::GetMotifData(motif,slot='motif.names'),positions=lapply(positions,as.data.frame),seed_before=before,seed_after=after,peak_names=peak.names)
 })
 stopifnot(identical(BSgenome::getSeq,canonicalGetSeq))
 row<-list(id=case$id,profile=profile,result=result,folder=basename(folder),qualified_getSeq_restored=TRUE)
 if(!'error'%in%names(result$value)){
  replay<-capture(function(){selected<-features;bg<-background;if(is.null(bg))bg<-rownames(object);.Random.seed<<-before;if(is.numeric(bg)){choose<-meta[setdiff(rownames(meta),selected),,drop=FALSE];if(profile!='1.6.0-source'&&length(setdiff(selected,rownames(meta)))>0L)selected<-intersect(selected,rownames(meta));query<-meta[selected,,drop=FALSE];bg<-env$MatchRegionStats(meta.feature=choose,query.feature=query,regions=selected,n=bg,verbose=FALSE,features.match=unlist(case$features_match))};stopifnot(identical(after,.Random.seed));list(effective_query=selected,effective_background=bg,replay_after=.Random.seed)})
  if('error'%in%names(replay$value))row$replay_error<-replay else row$replay<-replay
 }
 results[[length(results)+1L]]<-row;cat(index,profile,case$id,'\n')
}
writeLines(capture.output(sessionInfo()),file.path(args[[3]],'session-info.txt'));jsonlite::write_json(list(status='captured-original-FASTA-PFM-scan-and-enrichment-controls',results=results),args[[2]],pretty=TRUE,auto_unbox=TRUE,digits=17,na='string',null='null');cat('COMPLETE_ORIGINAL_SCAN_CONTROLS',length(results),'\n')
